let BIKES_DATA = {};

const GOOGLE_SHEET_CSV_URL = "https://docs.google.com/spreadsheets/d/1AgAF6D5OmeSm2ipUKmcDuduRaivJBo0M7tPy9ip0FZM/export?format=csv";

// Helper to convert Google Drive viewing URLs into direct image URLs
function convertDriveUrl(url) {
    if (!url) return "";
    const match = url.match(/drive\.google\.com\/file\/d\/([a-zA-Z0-9_-]+)/);
    if (match && match[1]) {
        return `https://drive.google.com/uc?export=view&id=${match[1]}`;
    }
    return url;
}

// Function to process parsed CSV data
function processCSVData(data) {
    data.forEach(row => {
        const bikeNameFull = row['BIKE NAME']?.trim();
        const accName = row['Accessory Name']?.trim();
        let priceRaw = row['Price']?.trim() || "0";
        let mrpRaw = row['MRP']?.trim() || "0";
        const img1 = row['Image 1']?.trim();

        if (!bikeNameFull || !accName) return; // Skip empty rows

        const bikeModel = bikeNameFull.toUpperCase(); // Ensure uniform casing
        const cleanPrice = parseFloat(priceRaw.replace(/[^0-9.-]+/g, ""));
        const cleanMrp = parseFloat(mrpRaw.replace(/[^0-9.-]+/g, ""));

        PRODUCTS.push({
            id: Math.random().toString(36).substr(2, 9),
            name: accName,
            bike: bikeModel,
            category: "Accessories",
            price: isNaN(cleanPrice) ? 0 : cleanPrice,
            mrp: isNaN(cleanMrp) ? 0 : cleanMrp,
            tag: "",
            image: convertDriveUrl(img1) || ""
        });
    });
}

// Load Local Bikes JSON
fetch('./static/data/bikes.json')
    .then(res => res.json())
    .then(data => {
        BIKES_DATA = data;
        if (typeof renderBrands === 'function') renderBrands();
        if (typeof renderProductsList === 'function') renderProductsList();
    })
    .catch(err => console.error("Error loading bikes.json", err));

// Dynamically load PapaParse for CSV processing
const papaScript = document.createElement('script');
papaScript.src = "https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.4.1/papaparse.min.js";
papaScript.onload = () => {
    Papa.parse(GOOGLE_SHEET_CSV_URL, {
        download: true,
        header: true,
        skipEmptyLines: true,
        complete: function(results) {
            processCSVData(results.data);
            if (typeof renderProductsList === 'function') renderProductsList();
            if (typeof renderProductDetails === 'function') renderProductDetails(); // Re-render if on product.html
        },
        error: function(error) {
            console.error("Error loading Google Sheet CSV:", error);
        }
    });
};
document.head.appendChild(papaScript);
